class Solution {public int solve(int n,int[][] edges){ArrayList<ArrayList<Integer>> adj=new ArrayList<>();for(int i=0;i<n;i++)adj.add(new ArrayList<>());for(int[] e:edges){adj.get(e[0]).add(e[1]);adj.get(e[1]).add(e[0]);}boolean[] seen=new boolean[n];int answer=0;for(int s=0;s<n;s++)if(!seen[s]){answer++;ArrayDeque<Integer>q=new ArrayDeque<>();q.add(s);seen[s]=true;while(!q.isEmpty())for(int v:adj.get(q.remove()))if(!seen[v]){seen[v]=true;q.add(v);}}return answer;}}